  Lemma ipf_fail_exit : forall e loc, 1 <= e <= 28 -> Z.even loc = true -> 4 <= loc -> loc + 1 < 2^64 -> http_fail (EC_http_loc e loc).
  Proof.
    intros e loc HE EV L1 L2. unfold http_fail, EC_http_loc, ec_make_loc, ec_failed, ec_ok. cbn [ec_val ec_cat ec_flags].
    replace (e =? 0) with false by (symmetry; apply Z.eqb_neq; lia).
    unfold AG_HTTP_CAT. repeat split; try lia. rewrite Z.odd_add. cbn. rewrite <- Z.negb_even, EV. reflexivity.
  Qed.
