Ltac dbnd_lia BND ::= clear - BND; unfold dof_bnd, ipf_bnd in BND; lia.

(* [comment removed for export] *)
Ltac ipf_s1_for_exit S1F :=
  lazymatch type of S1F with rw_cells _ _ ?spa (?c0 :: ?rest) =>
    let R := fresh "S1R" in
    split_frameA S1F [c0] rest S1F R; blob_at spa;
    lazymatch goal with BL : rw_cells _ _ spa [CB _ _] |- _ => join_frameA BL R spa; rename BL into S1F end
  end.

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac ipfx_ec_blob EC ESZ :=
  let ej := fresh "ej" in let ECj := fresh "ECj" in
  destruct (rw_cells_forget _ _ _ _ EC) as [ej ECj]; clear EC;
  lazymatch type of ECj with rw_cells _ _ _ [CB (cells_size ?ecs) _] => replace (cells_size ecs) with 24%nat in ECj by (clear - ESZ; lia) end;
  rename ECj into EC.

Ltac ipfx_prelude HH sp SD PURE WIN MU PC S1 :=
  destruct PURE as ((PCOK & LBS & LO & CEIL & PAL & EAL & SPI & ISH & IAL & DPE & DWP & DWE & SPAL & SHI) & (GAPE & SPA1 & SPA32) & LAST & APP & APE & APW);
  destruct (ipf_ff_nums _ HH _ _ _ _ _ _ _ _ _ _ _ SD) as (FF & APF & N1 & N2 & N3 & N4 & N5 & N6 & N7 & SHFF & NSF & NSP & N64);
  destruct (ipf_obj_sep _ HH _ _ _ _ _ _ _ _ _ _ _ SD) as (DPF & DEF & DWF & DPP & DEP & DWP1 & DPS & DES & DWS);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APP ltac:(clear; lia)) as (PB1 & PB2 & PB3 & PB4 & _);
  pose proof (aapp_bounds _ _ APE ltac:(clear; lia)) as (EB1 & EB2 & EB3 & EB4 & _);
  pose proof (aapp_bounds _ _ APW ltac:(clear; lia)) as (VB1 & VB2 & VB3 & VB4 & _);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & AF2 & _);
  unfold AIMG_TOP, AAPP_HI in PB1, PB3, EB1, EB3, VB1, VB3;
  unfold ipf_WX, ipf_W, IPF_STACK, AASSIGN_STACK, AINTRIN_STACK, AFS_STACK, AFS_FLAGS, AG_HTTP_CAT, AG_FIELD_TABLE, AG_FIELD_TABLE_GUARD in *;
  rewrite <- ?SHFF in MU; cbn [app] in MU;
