Lemma ipf_done : forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s4x s5x s6x s7x s8x s11x t3 t4 t5 t6 : word)
    (LF : list fframe) (m m1 : mem) (spa : Z) (gsz : nat) (gj j96 jr jh shb : list byte) (cst hi cb : list cell) (XS : list (Z * Z))
    (P IN E p0 lo shi ff fp last : Z) (bs : list byte) (c c1 : pcore) (pad7 pad2 : list byte) (qlo q p : Z) (E' : ecv) (g : bool)
    (h0 h1 h2 h3 : word),
  rw_cells bsegs m1 (spa + 184) [CB gsz gj] ->
  rw_cells bsegs m1 (bv_unsigned sp + -104) (dof_sav s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
  rw_cells bsegs m1 spa (ipf_s1f P E IN ff j96) ->
  rw_cells bsegs m1 (spa + 120) cst -> Z.of_nat (cells_size cst) = 24 ->
  rw_cells bsegs m1 (spa + 144) (C8 (wz p) :: hi) -> Z.of_nat (cells_size hi) = 32 ->
  rw_cells bsegs m1 ff [C8 h0; C8 h1; C8 h2; C8 h3] -> rw_cells bsegs m1 (ff + 4136) [CB 4048 jr] -> rw_cells bsegs m1 (ff + 8184) [C8 (wz fp)] ->
  rw_cells bsegs m1 (Z.shiftr ff 3 + 2147450880) [CB 552 shb] -> rw_cells bsegs m1 (Z.shiftr ff 3 + 2147450880 + 552) [CB 472 jh] ->
  rw_cells bsegs m1 fp [C1 (b8 1)] ->
  rw_cells bsegs m1 (ff + 32) cb -> Z.of_nat (cells_size cb) = 4104 ->
  stk bsegs m1 lo spa -> mem_inv bsegs m1 ->
  ipf_side H LF m m1 lo shi ff fp P E p0 (Z.of_nat (length bs)) ->
  munch (ipf_WX H lo sp P IN E ff fp ++ XS) m m1 -> Forall (fs_scratch H ((7, ff, fp) :: LF)) XS -> wmono bsegs m m1 ->
  rw_cells bsegs m1 P (ParserCoreCells c1 pad7 pad2) -> dof_core c c1 ->
  rw_cells bsegs m1 IN [C8 (wz q)] ->
  rw_cells bsegs m1 E (ErrCodeCells E') -> (E' = EC_clear \/ http_fail E') ->
  bytes_at bsegs m1 p0 bs -> APfTab m1 -> (AFieldTabZero m1 \/ FT m1) -> FTInit m1 -> AHttpCat m1 g ->
  ipf_bpure sp spa gsz P IN E lo shi c p0 last bs -> bv_unsigned ra mod 2 = 0 ->
  qlo <= p + 2 -> p0 <= p -> p + 2 <= p0 + Z.of_nat (length bs) ->
  evt bsegs (ipf_ret_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P IN E lo shi c pad7 pad2 p0 bs qlo m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             s2x (wz E) s4x s5x s6x s7x s8x (wz (E + 16)) (wz IN) s11x t3 t4 t5 t6)
